// Forfeit Skies Mod Book (Patchouli book "forfeit:mods", generated by docs/guide-tools/build-modbook.mjs).
// Every player gets one copy the first time they join; lost it? Craft a book + compass.
const MOD_BOOK = 'patchouli:guide_book[patchouli:book="forfeit:mods"]'

PlayerEvents.loggedIn(event => {
  const player = event.player
  if (!player.persistentData.getBoolean('forfeit_got_modbook')) {
    player.give(Item.of(MOD_BOOK))
    player.persistentData.putBoolean('forfeit_got_modbook', true)
    player.tell(Text.of('[Forfeit Skies] ').darkPurple().append(Text.of('Here is the Mod Book: every mod in the pack, grouped by type.').gray()))
  }
})

ServerEvents.recipes(event => {
  event.shapeless(Item.of(MOD_BOOK), ['minecraft:book', 'minecraft:compass']).id('forfeit:mod_book')
})
